// AutoCloseable so try-with-resources closes it deterministically.
// This REPLACES the old, unreliable finalize() cleanup approach.
class LedgerConnection implements AutoCloseable {
    private static final Logger log = Logger.getLogger("BankLog");
    LedgerConnection() { log.fine("Ledger connection OPENED"); }
    void record(String entry) { log.info(() -> "LEDGER: " + entry); }
    @Override public void close() { log.info("Ledger connection CLOSED (returned to pool)"); }
}

// ─── Would be TransferService.java in a real project ───
class TransferService {
    private static final Logger log = Logger.getLogger("BankLog");
    private final AccountRepository repo;
    TransferService(AccountRepository repo) { this.repo = repo; }

    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = repo.findById(fromId);
        Account to = repo.findById(toId);
        // try-with-resources guarantees close() runs like a finally block,
        // whether the transfer succeeds or throws.
        try (LedgerConnection ledger = new LedgerConnection()) {
            from.debit(amount.add(FinalFinallyFinalizeDemo.TRANSFER_FEE));
            to.credit(amount);
            ledger.record(fromId + "->" + toId + " amount " + amount
                          + " fee " + FinalFinallyFinalizeDemo.TRANSFER_FEE);
            log.info(() -> fromId + " balance " + from.getBalance()
                          + ", " + toId + " balance " + to.getBalance());
        }
    }
}
